const items = $input.all();

// Read and validate student rows
const students = items
  .map(item => item.json)
  .filter(row =>
    String(row.Name ?? "").trim() !== "" &&
    String(row.Course ?? "").trim() !== "" &&
    String(row.Status ?? "").trim() !== ""
  );

// Do not create an email when no valid rows exist
if (students.length === 0) {
  return [];
}

// Escape special HTML characters
function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, char => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  }[char]));
}

// Calculate student statistics
const completed = students.filter(
  s => String(s.Status).trim().toLowerCase() === "completed"
).length;

const inProgress = students.filter(
  s => String(s.Status).trim().toLowerCase() === "in progress"
).length;

const pending = students.filter(
  s => String(s.Status).trim().toLowerCase() === "pending"
).length;

// Generate HTML table rows
const tableRows = students.map((student, index) => `
  <tr>
    <td style="padding:10px;border:1px solid #ddd;">
      ${index + 1}
    </td>
    <td style="padding:10px;border:1px solid #ddd;">
      ${escapeHtml(student.Name)}
    </td>
    <td style="padding:10px;border:1px solid #ddd;">
      ${escapeHtml(student.Course)}
    </td>
    <td style="padding:10px;border:1px solid #ddd;">
      ${escapeHtml(student.Status)}
    </td>
  </tr>
`).join("");

// Generate email subject
const subject = `Student Course Status Report - ${students.length} Students`;

// Generate email body
const body = `
<html>
<body style="font-family:Arial,sans-serif;color:#333;">

  <h2 style="color:#176b46;">
    Student Course Status Report
  </h2>

  <p>Hello Team,</p>

  <p>
    Please find below the latest student course
    status report generated from Google Sheets.
  </p>

  <h3>Summary</h3>

  <ul>
    <li>Total Students: ${students.length}</li>
    <li>Completed: ${completed}</li>
    <li>In Progress: ${inProgress}</li>
    <li>Pending: ${pending}</li>
  </ul>

  <h3>Student Details</h3>

  <table style="border-collapse:collapse;width:100%;">
    <thead>
      <tr style="background-color:#176b46;color:white;">
        <th style="padding:10px;border:1px solid #ddd;">#</th>
        <th style="padding:10px;border:1px solid #ddd;">Name</th>
        <th style="padding:10px;border:1px solid #ddd;">Course</th>
        <th style="padding:10px;border:1px solid #ddd;">Status</th>
      </tr>
    </thead>
    <tbody>
      ${tableRows}
    </tbody>
  </table>

  <p>Regards,<br>
  n8n Automation</p>

  <p style="font-size:12px;color:#777;">
    This is an automatically generated email.
  </p>

</body>
</html>
`;

// Return a single email item
return [{
  json: {
    subject,
    body,
    studentCount: students.length,
    completed,
    inProgress,
    pending
  }
}];
